import{at as e,it as t,n,vt as r}from"./chunks/framework.BUQROvXk.js";var i=JSON.parse(`{"title":"Class: Config","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/prismarine/classes/Config.md","filePath":"api/@jsprismarine/prismarine/classes/Config.md"}`),a={name:`api/@jsprismarine/prismarine/classes/Config.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/prismarine</a> / Config</p><h1 id="class-config" tabindex="-1">Class: Config <a class="header-anchor" href="#class-config" aria-label="Permalink to “Class: Config”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L187" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:187</a></p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new Config</strong>(<code>options?</code>): <code>Config</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L264" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:264</a></p><p>Creates the server configuration.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./../#configoptions"><code>ConfigOptions</code></a> = <code>{}</code></p><p>runtime values that override settings in the server config file.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Config</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="getchunksendbudgetms" tabindex="-1">getChunkSendBudgetMs() <a class="header-anchor" href="#getchunksendbudgetms" aria-label="Permalink to “getChunkSendBudgetMs()”">​</a></h3><blockquote><p><strong>getChunkSendBudgetMs</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L505" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:505</a></p><p>How long a tick may spend sending chunks, out of the 50 ms it has.</p><p>The dial between how responsive the server stays and how fast the world appears. Raising it loads chunks quicker at the cost of everything else the tick does.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The budget in milliseconds</p><hr><h3 id="getchunkworkers" tabindex="-1">getChunkWorkers() <a class="header-anchor" href="#getchunkworkers" aria-label="Permalink to “getChunkWorkers()”">​</a></h3><blockquote><p><strong>getChunkWorkers</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L482" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:482</a></p><p>How many worker threads chunk generation may use.</p><p>Zero keeps generation on the server thread. The default reserves two cores for the server and caps the rest at the number already measured to help generation.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>A nonnegative integer worker count</p><hr><h3 id="getcraftingrecipelimit" tabindex="-1">getCraftingRecipeLimit() <a class="header-anchor" href="#getcraftingrecipelimit" aria-label="Permalink to “getCraftingRecipeLimit()”">​</a></h3><blockquote><p><strong>getCraftingRecipeLimit</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L628" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:628</a></p><p>How many recipes to send: <code>-1</code> for every one, <code>0</code> for none, a positive number to cap.</p><p>The <code>crafting-recipe-limit</code> config key, truncated to a whole number. This is how <code>PlayerSession.sendCraftingData</code> reads it; the field above says why the two escape hatches exist.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>the limit.</p><hr><h3 id="getdifficulty" tabindex="-1">getDifficulty() <a class="header-anchor" href="#getdifficulty" aria-label="Permalink to “getDifficulty()”">​</a></h3><blockquote><p><strong>getDifficulty</strong>(): <a href="./../../minecraft/#difficulty"><code>Difficulty</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L403" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:403</a></p><p>How dangerous the monsters are.</p><p>Named in the file rather than numbered, as the gamemode is, because <code>difficulty: 2</code> in a config nobody can read is how a server ends up on the wrong one. An unrecognized name falls back to normal instead of refusing to start - a typo should not take a server down.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../minecraft/#difficulty"><code>Difficulty</code></a></p><p>The configured difficulty.</p><hr><h3 id="getenableprocesstitle" tabindex="-1">getEnableProcessTitle() <a class="header-anchor" href="#getenableprocesstitle" aria-label="Permalink to “getEnableProcessTitle()”">​</a></h3><blockquote><p><strong>getEnableProcessTitle</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L612" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:612</a></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="getenablequery" tabindex="-1">getEnableQuery() <a class="header-anchor" href="#getenablequery" aria-label="Permalink to “getEnableQuery()”">​</a></h3><blockquote><p><strong>getEnableQuery</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L608" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:608</a></p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="getenableticking" tabindex="-1">getEnableTicking() <a class="header-anchor" href="#getenableticking" aria-label="Permalink to “getEnableTicking()”">​</a></h3><blockquote><p><strong>getEnableTicking</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L616" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:616</a></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="getentitytrackinghysteresis" tabindex="-1">getEntityTrackingHysteresis() <a class="header-anchor" href="#getentitytrackinghysteresis" aria-label="Permalink to “getEntityTrackingHysteresis()”">​</a></h3><blockquote><p><strong>getEntityTrackingHysteresis</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L544" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:544</a></p><p>Chunks past a viewer&#39;s own reach before a tracked entity is taken off their screen.</p><p>The gap between the radius at which an entity appears and the one at which it goes away. Without a gap, a player standing on the boundary makes every entity out there appear and disappear on alternating passes.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The hysteresis in chunks, as an <code>integer</code></p><hr><h3 id="getentitytrackinginterval" tabindex="-1">getEntityTrackingInterval() <a class="header-anchor" href="#getentitytrackinginterval" aria-label="Permalink to “getEntityTrackingInterval()”">​</a></h3><blockquote><p><strong>getEntityTrackingInterval</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L557" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:557</a></p><p>Ticks between entity visibility passes.</p><p>Only governs entities moving towards a standing player - a player who moves crosses a chunk boundary and forces a pass regardless. Entity types that declare a longer interval of their own keep it; this is the floor.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The interval in ticks, at least 1</p><hr><h3 id="getgamemode" tabindex="-1">getGamemode() <a class="header-anchor" href="#getgamemode" aria-label="Permalink to “getGamemode()”">​</a></h3><blockquote><p><strong>getGamemode</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L391" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:391</a></p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="getlevelname" tabindex="-1">getLevelName() <a class="header-anchor" href="#getlevelname" aria-label="Permalink to “getLevelName()”">​</a></h3><blockquote><p><strong>getLevelName</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L359" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:359</a></p><p>Returns the default world&#39;s name (<code>id</code>).</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><p>The world&#39;s name as a <code>string</code></p><h4 id="remarks" tabindex="-1">Remarks <a class="header-anchor" href="#remarks" aria-label="Permalink to “Remarks”">​</a></h4><p>If the world doesn&#39;t exist as a part of the <code>worlds</code> array the <code>worldManager</code> will fail to initialize.</p><hr><h3 id="getlogexcludedpackets" tabindex="-1">getLogExcludedPackets() <a class="header-anchor" href="#getlogexcludedpackets" aria-label="Permalink to “getLogExcludedPackets()”">​</a></h3><blockquote><p><strong>getLogExcludedPackets</strong>(): <code>string</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L636" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:636</a></p><p>Packet class names kept out of the traffic log.</p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code>[]</p><p>the excluded names.</p><hr><h3 id="getloglevel" tabindex="-1">getLogLevel() <a class="header-anchor" href="#getloglevel" aria-label="Permalink to “getLogLevel()”">​</a></h3><blockquote><p><strong>getLogLevel</strong>(): <code>&quot;warn&quot;</code> | <code>&quot;error&quot;</code> | <code>&quot;info&quot;</code> | <code>&quot;verbose&quot;</code> | <code>&quot;debug&quot;</code> | <code>&quot;silly&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L330" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:330</a></p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h4><p><code>&quot;warn&quot;</code> | <code>&quot;error&quot;</code> | <code>&quot;info&quot;</code> | <code>&quot;verbose&quot;</code> | <code>&quot;debug&quot;</code> | <code>&quot;silly&quot;</code></p><hr><h3 id="getmaxplayers" tabindex="-1">getMaxPlayers() <a class="header-anchor" href="#getmaxplayers" aria-label="Permalink to “getMaxPlayers()”">​</a></h3><blockquote><p><strong>getMaxPlayers</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L387" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:387</a></p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The max amount of players allowed onto the server at the same time.</p><hr><h3 id="getmotd" tabindex="-1">getMotd() <a class="header-anchor" href="#getmotd" aria-label="Permalink to “getMotd()”">​</a></h3><blockquote><p><strong>getMotd</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L437" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:437</a></p><p>Returns true or false depending on if online mode is enabled.</p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><p>The message of the day as a <code>string</code></p><hr><h3 id="getonlinemode" tabindex="-1">getOnlineMode() <a class="header-anchor" href="#getonlinemode" aria-label="Permalink to “getOnlineMode()”">​</a></h3><blockquote><p><strong>getOnlineMode</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L566" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:566</a></p><p>Returns true or false depending on if online mode is enabled.</p><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p><code>true</code> if enabled, <code>false</code> otherwise</p><hr><h3 id="getpacketcompressionalgorithm" tabindex="-1">getPacketCompressionAlgorithm() <a class="header-anchor" href="#getpacketcompressionalgorithm" aria-label="Permalink to “getPacketCompressionAlgorithm()”">​</a></h3><blockquote><p><strong>getPacketCompressionAlgorithm</strong>(): <a href="./../../minecraft/#packetcompressionalgorithm"><code>PacketCompressionAlgorithm</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L587" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:587</a></p><p>The algorithm selected for new connections. Each <code>NetworkSettings</code> packet advertises it, and the connection stores the same value for all later batches.</p><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../minecraft/#packetcompressionalgorithm"><code>PacketCompressionAlgorithm</code></a></p><hr><h3 id="getpacketcompressionlevel" tabindex="-1">getPacketCompressionLevel() <a class="header-anchor" href="#getpacketcompressionlevel" aria-label="Permalink to “getPacketCompressionLevel()”">​</a></h3><blockquote><p><strong>getPacketCompressionLevel</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L579" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:579</a></p><p>The zlib level batches are compressed at, clamped to what zlib will actually accept. See <a href="./../#topacketcompressionlevel">toPacketCompressionLevel</a> for why the configured value is not trusted as is.</p><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getpacketcompressionthreshold" tabindex="-1">getPacketCompressionThreshold() <a class="header-anchor" href="#getpacketcompressionthreshold" aria-label="Permalink to “getPacketCompressionThreshold()”">​</a></h3><blockquote><p><strong>getPacketCompressionThreshold</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L599" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:599</a></p><p>The minimum uncompressed batch-body size that is compressed and advertised to clients.</p><h4 id="returns-19" tabindex="-1">Returns <a class="header-anchor" href="#returns-19" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getpacketfullflushfragments" tabindex="-1">getPacketFullFlushFragments() <a class="header-anchor" href="#getpacketfullflushfragments" aria-label="Permalink to “getPacketFullFlushFragments()”">​</a></h3><blockquote><p><strong>getPacketFullFlushFragments</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L604" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:604</a></p><p>Whether the unvalidated full-flush batch prototype is enabled for shared movement, blocks, and chunks.</p><h4 id="returns-20" tabindex="-1">Returns <a class="header-anchor" href="#returns-20" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="getpreloadradius" tabindex="-1">getPreloadRadius() <a class="header-anchor" href="#getpreloadradius" aria-label="Permalink to “getPreloadRadius()”">​</a></h3><blockquote><p><strong>getPreloadRadius</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L470" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:470</a></p><p>How many chunks around spawn are generated before the server accepts players.</p><p>A radius of r generates (2r+1)^2 chunks, so the default 10 is 441 - about what the first player will see. Zero skips the preload entirely and generates on demand.</p><h4 id="returns-21" tabindex="-1">Returns <a class="header-anchor" href="#returns-21" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The preload radius in chunks, as an <code>integer</code></p><hr><h3 id="getproximitybroadcast" tabindex="-1">getProximityBroadcast() <a class="header-anchor" href="#getproximitybroadcast" aria-label="Permalink to “getProximityBroadcast()”">​</a></h3><blockquote><p><strong>getProximityBroadcast</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L518" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:518</a></p><p>Whether positional packets are narrowed to the players near them.</p><p>An escape hatch rather than a feature dial. Turning it off makes every positional broadcast reach every player <em>in the same world</em> - it does not restore the server-wide fan-out some of them used to have, which was a bug and not a behavior.</p><h4 id="returns-22" tabindex="-1">Returns <a class="header-anchor" href="#returns-22" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>Whether proximity filtering is on</p><hr><h3 id="getserverauthoritativeblockbreaking" tabindex="-1">getServerAuthoritativeBlockBreaking() <a class="header-anchor" href="#getserverauthoritativeblockbreaking" aria-label="Permalink to “getServerAuthoritativeBlockBreaking()”">​</a></h3><blockquote><p><strong>getServerAuthoritativeBlockBreaking</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L531" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:531</a></p><p>Who decides when a block a player is mining breaks.</p><p>On, the default and what a Bedrock Dedicated Server 1.26.52 announces: the server animates the cracks every tick, and the client reports a break it predicts, which the server carries out. Off, the client times the break itself and reports it once it is done.</p><h4 id="returns-23" tabindex="-1">Returns <a class="header-anchor" href="#returns-23" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>Whether block breaking is server-authoritative</p><hr><h3 id="getserverip" tabindex="-1">getServerIp() <a class="header-anchor" href="#getserverip" aria-label="Permalink to “getServerIp()”">​</a></h3><blockquote><p><strong>getServerIp</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L348" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:348</a></p><p>Get the server&#39;s IP address.</p><h4 id="returns-24" tabindex="-1">Returns <a class="header-anchor" href="#returns-24" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><p>The server&#39;s IP address</p><h4 id="remarks-1" tabindex="-1">Remarks <a class="header-anchor" href="#remarks-1" aria-label="Permalink to “Remarks”">​</a></h4><p>The default IP address is <code>0.0.0.0</code></p><hr><h3 id="getserverport" tabindex="-1">getServerPort() <a class="header-anchor" href="#getserverport" aria-label="Permalink to “getServerPort()”">​</a></h3><blockquote><p><strong>getServerPort</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L339" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:339</a></p><p>Get the server&#39;s port.</p><h4 id="returns-25" tabindex="-1">Returns <a class="header-anchor" href="#returns-25" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The server&#39;s port</p><h4 id="remarks-2" tabindex="-1">Remarks <a class="header-anchor" href="#remarks-2" aria-label="Permalink to “Remarks”">​</a></h4><p>The default port is <code>19132</code>.</p><hr><h3 id="getterraincachesizemb" tabindex="-1">getTerrainCacheSizeMb() <a class="header-anchor" href="#getterraincachesizemb" aria-label="Permalink to “getTerrainCacheSizeMb()”">​</a></h3><blockquote><p><strong>getTerrainCacheSizeMb</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L492" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:492</a></p><p>How many megabytes of generated terrain tiles the server keeps on disk.</p><h4 id="returns-26" tabindex="-1">Returns <a class="header-anchor" href="#returns-26" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>A nonnegative integer; zero turns the cache off</p><hr><h3 id="getuseraknetworker" tabindex="-1">getUseRakNetWorker() <a class="header-anchor" href="#getuseraknetworker" aria-label="Permalink to “getUseRakNetWorker()”">​</a></h3><blockquote><p><strong>getUseRakNetWorker</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L571" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:571</a></p><p>Whether RakNet UDP I/O and reliability updates run outside the game thread.</p><h4 id="returns-27" tabindex="-1">Returns <a class="header-anchor" href="#returns-27" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="getviewdistance" tabindex="-1">getViewDistance() <a class="header-anchor" href="#getviewdistance" aria-label="Permalink to “getViewDistance()”">​</a></h3><blockquote><p><strong>getViewDistance</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L458" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:458</a></p><p>Returns the view distance.</p><h4 id="returns-28" tabindex="-1">Returns <a class="header-anchor" href="#returns-28" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The view distance as an <code>integer</code></p><hr><h3 id="getworlds" tabindex="-1">getWorlds() <a class="header-anchor" href="#getworlds" aria-label="Permalink to “getWorlds()”">​</a></h3><blockquote><p><strong>getWorlds</strong>(): <code>Record</code>&lt;<code>string</code>, <code>WorldData</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L363" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:363</a></p><h4 id="returns-29" tabindex="-1">Returns <a class="header-anchor" href="#returns-29" aria-label="Permalink to “Returns”">​</a></h4><p><code>Record</code>&lt;<code>string</code>, <code>WorldData</code>&gt;</p><hr><h3 id="setdifficulty" tabindex="-1">setDifficulty() <a class="header-anchor" href="#setdifficulty" aria-label="Permalink to “setDifficulty()”">​</a></h3><blockquote><p><strong>setDifficulty</strong>(<code>difficulty</code>, <code>commit?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L426" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:426</a></p><p>Set how dangerous the monsters are.</p><p>Stored by name, as the file spells it, so <code>getDifficulty</code> reads back what was set rather than a second copy of the number.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="difficulty" tabindex="-1">difficulty <a class="header-anchor" href="#difficulty" aria-label="Permalink to “difficulty”">​</a></h5><p><a href="./../../minecraft/#difficulty"><code>Difficulty</code></a></p><p>the difficulty</p><h5 id="commit" tabindex="-1">commit? <a class="header-anchor" href="#commit" aria-label="Permalink to “commit?”">​</a></h5><p><code>boolean</code> = <code>false</code></p><p>if the value should be written to the <code>config.json</code> file</p><h4 id="returns-30" tabindex="-1">Returns <a class="header-anchor" href="#returns-30" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setgamemode" tabindex="-1">setGamemode() <a class="header-anchor" href="#setgamemode" aria-label="Permalink to “setGamemode()”">​</a></h3><blockquote><p><strong>setGamemode</strong>(<code>gamemode</code>, <code>commit?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L413" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:413</a></p><p>Set the default gamemode.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="gamemode" tabindex="-1">gamemode <a class="header-anchor" href="#gamemode" aria-label="Permalink to “gamemode”">​</a></h5><p><code>number</code></p><p>the gamemode</p><h5 id="commit-1" tabindex="-1">commit? <a class="header-anchor" href="#commit-1" aria-label="Permalink to “commit?”">​</a></h5><p><code>boolean</code> = <code>false</code></p><p>whether to write the value to the server config file</p><h4 id="returns-31" tabindex="-1">Returns <a class="header-anchor" href="#returns-31" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setmotd" tabindex="-1">setMotd() <a class="header-anchor" href="#setmotd" aria-label="Permalink to “setMotd()”">​</a></h3><blockquote><p><strong>setMotd</strong>(<code>motd</code>, <code>commit?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L447" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:447</a></p><p>Set the motd.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="motd" tabindex="-1">motd <a class="header-anchor" href="#motd" aria-label="Permalink to “motd”">​</a></h5><p><code>string</code></p><p>the gamemode</p><h5 id="commit-2" tabindex="-1">commit? <a class="header-anchor" href="#commit-2" aria-label="Permalink to “commit?”">​</a></h5><p><code>boolean</code> = <code>false</code></p><p>whether to write the value to the server config file</p><h4 id="returns-32" tabindex="-1">Returns <a class="header-anchor" href="#returns-32" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setworld" tabindex="-1">setWorld() <a class="header-anchor" href="#setworld" aria-label="Permalink to “setWorld()”">​</a></h3><blockquote><p><strong>setWorld</strong>(<code>name</code>, <code>data</code>, <code>commit?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L378" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:378</a></p><p>Replaces one <code>worlds</code> entry, which is how an entry read in the old <code>generator</code> and <code>layers</code> spelling is written back as <code>preset</code> and <code>dimensions</code> so the file converges.</p><p>The whole <code>worlds</code> map is rewritten, because the file keeps its top-level keys and their comments but a replaced map loses the comments inside it. Nothing else in the file moves.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><p>The world&#39;s key under <code>worlds</code>.</p><h5 id="data" tabindex="-1">data <a class="header-anchor" href="#data" aria-label="Permalink to “data”">​</a></h5><p><code>WorldData</code></p><p>The entry to store, normally from <code>worldDataOf</code>.</p><h5 id="commit-3" tabindex="-1">commit? <a class="header-anchor" href="#commit-3" aria-label="Permalink to “commit?”">​</a></h5><p><code>boolean</code> = <code>false</code></p><p>Whether to write the map to the config file.</p><h4 id="returns-33" tabindex="-1">Returns <a class="header-anchor" href="#returns-33" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to “Lifecycle”">​</a></h2><h3 id="disable" tabindex="-1">disable() <a class="header-anchor" href="#disable" aria-label="Permalink to “disable()”">​</a></h3><blockquote><p><strong>disable</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L328" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:328</a></p><p>On disable hook.</p><h4 id="returns-34" tabindex="-1">Returns <a class="header-anchor" href="#returns-34" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="enable" tabindex="-1">enable() <a class="header-anchor" href="#enable" aria-label="Permalink to “enable()”">​</a></h3><blockquote><p><strong>enable</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/29b5e0ea160745ec31d7e25055872c383b5fa127/packages/prismarine/src/config/Config.ts#L278" target="_blank" rel="noreferrer">prismarine/src/config/Config.ts:278</a></p><p>On enable hook.</p><p>Reads every setting, writing the default and its comment into the file for any key the file does not have yet. A file from an older version therefore gains the new keys, explained, without losing anything a person wrote in it.</p><h4 id="returns-35" tabindex="-1">Returns <a class="header-anchor" href="#returns-35" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p>`,319)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};